/**
 * P17 independent seeded raw-material-lot / process-quality campaign.
 *
 * P16 varied only fault position while retaining a single feeder RNG state.
 * P17 seeds a NEW EMPTY private plant Worker per lot BEFORE the first
 * electrical PLC scan. The real feeder still manufactures every workpiece
 * on a user-programmed Q rising edge, and every material/quality result is
 * read from the final original bodies (not generated by this auditor).
 *
 * Three independently seeded lots cover C-C-M, C-M-C, M-C-C for the robot,
 * and a fourth run proves exact material/quality replay. A correct grading
 * result cannot be borrowed from another lot or saved as a project field.
 */
import type {ProjectFile} from '../../sim/signals';
import {nextSeed} from '../world/seed';
import {projectSignature} from './commissioning';
import {p16AuditPreflight,type P16Scene} from './matrix-p16';
import {runP15AutonomousFactory} from './matrix-p15-autonomous-factory';
import {runP15AutonomousSort} from './matrix-p15-autonomous';
import {materialCode,type P17MaterialTrace} from './p17-product-trace';

export const P17_MATERIAL_SEEDS=[1,42,65535] as const;
const SCENES=['robot-sort','gantry-transfer','palletizing','bottle-line'] as const;
type LotId='lot-a'|'lot-b'|'lot-c'|'replay-b';
export type P17Lot={
 id:LotId;materialSeed:number;faultAtProduct:number;
 status:'passed'|'failed'|'blocked';pass:boolean;
 produced:number;accepted:number;expected:number;
 materialSequence:string;trace:readonly P17MaterialTrace[];
 faultRecovered:boolean;simulatedMs:number;throughputPerSimHour:number;
 diagnostic:string;
};
export type P17Campaign={
 sceneId:string;sourceSignature:string;status:'passed'|'failed'|'blocked';
 lots:readonly P17Lot[];expectedProducts:number;
 materialDiversity:boolean;deterministicReplay:boolean;
 totalPhysicalProducts:number;acceptedPhysicalProducts:number;
 qualityYieldPercent:number;minModelThroughputPerHour:number;
 maxModelThroughputPerHour:number;diagnostic:string;
};

const supported=(id:string):id is P16Scene=>
 (SCENES as readonly string[]).includes(id);
const productCount=(id:P16Scene):number=>id==='palletizing'?8:3;
function predictedMaterial(seed:number,count:number):string{
 let state=seed,result='';
 for(let i=0;i<count;i++){
  const r=nextSeed(state);state=r.state;
  result+=r.unit>.5?'M':'C';
 }
 return result;
}
const materialFromTrace=(trace:readonly P17MaterialTrace[])=>materialCode(trace);
function runLot(p:ProjectFile,scene:P16Scene,seed:number,index:number,id:LotId):P17Lot{
 const expected=productCount(scene);
 const result=scene==='robot-sort'?
  runP15AutonomousSort(p,scene,{faultAtProduct:index,materialSeed:seed}):
  runP15AutonomousFactory(p,scene,{faultAtProduct:index,materialSeed:seed});
 const accepted='sorted' in result?result.sorted:result.completed;
 const trace=result.productTrace;
 const materialSequence=materialFromTrace(trace);
 const bodyIDs=trace.map(item=>item.bodyId);
 const uniqueIDs=new Set(bodyIDs).size===bodyIDs.length;
 const sourced=trace.length===expected&&
  bodyIDs.every((bodyId,i)=>bodyId==='b'+(i+1));
 const validMaterial=materialSequence===predictedMaterial(seed,expected)&&
  trace.every(t=>t.material==='metal'||t.material==='cardboard');
 const measuredQuality=trace.every(t=>t.qualityPassed&&
  (scene!=='robot-sort'||(t.receivedAtMs!==null&&
   t.receivedBy===(t.material==='metal'?'metal-out':'plain-out')))&&
  (scene!=='bottle-line'||(t.shape==='cylinder'&&t.capped&&
   t.filledMl!==null&&t.filledMl>=500))&&
  (scene!=='palletizing'||t.palletSlot!==null));
 // The same PLC program must handle BOTH kinds of material in each
 // three-product robot lot; accepting only one material is not "sorting".
 const heterogeneous=scene!=='robot-sort'||(
  trace.some(t=>t.material==='metal')&&
  trace.some(t=>t.material==='cardboard'));
 const pass=result.status==='passed'&&result.materialSeed===seed&&
  result.produced===expected&&accepted===expected&&
  result.faultRecovered&&uniqueIDs&&sourced&&validMaterial&&
  measuredQuality&&heterogeneous&&Number.isFinite(result.simulatedMs)&&
  result.simulatedMs>0&&Number.isFinite(result.throughputPerSimHour)&&
  result.throughputPerSimHour>0;
 return {id,materialSeed:seed,faultAtProduct:index,
  status:result.status,pass,produced:result.produced,accepted,expected,
  materialSequence,trace,faultRecovered:result.faultRecovered,
  simulatedMs:result.simulatedMs,
  throughputPerSimHour:result.throughputPerSimHour,
  diagnostic:pass?
   'Powered PLC processed the feeder-generated seeded lot, conserved every original ID and satisfied the real workcell quality conditions':
   result.diagnostic+'; seeded material provenance, physical quality or recovery gate not met'};
}
const replayProof=(x:P17Lot)=>JSON.stringify({
 seed:x.materialSeed,faultAt:x.faultAtProduct,status:x.status,
 pass:x.pass,produced:x.produced,accepted:x.accepted,
 materialSequence:x.materialSequence,trace:x.trace,
 faultRecovered:x.faultRecovered,simulatedMs:x.simulatedMs,
 throughputPerSimHour:x.throughputPerSimHour,
});
/** All seeds are fixed public test-lot configurations. This audit does not
 * accept user-controlled arbitrary payloads from a browser or mutate PLC
 * tags/material provenance. It never certifies real manufacturing quality. */
export function runP17MaterialCampaign(p:ProjectFile,sceneId:string):P17Campaign{
 const sourceSignature=projectSignature(p);
 const expectedProducts=supported(sceneId)?productCount(sceneId):0;
 const base={sceneId,sourceSignature,expectedProducts,
  lots:[] as P17Lot[],materialDiversity:false,deterministicReplay:false,
  totalPhysicalProducts:0,acceptedPhysicalProducts:0,qualityYieldPercent:0,
  minModelThroughputPerHour:0,maxModelThroughputPerHour:0};
 const blockers=p16AuditPreflight(p,sceneId);
 if(blockers.length||!supported(sceneId))return {...base,
  status:'blocked',diagnostic:blockers.join('; ')};
 try{
  const faultPositions=sceneId==='palletizing'?[1,4,8]:[1,2,3];
  const lots:P17Lot[]=P17_MATERIAL_SEEDS.map((seed,i)=>
   runLot(p,sceneId,seed,faultPositions[i],(['lot-a','lot-b','lot-c'] as const)[i]));
  lots.push(runLot(p,sceneId,P17_MATERIAL_SEEDS[1],faultPositions[1],'replay-b'));
  const sequences=lots.slice(0,3).map(lot=>lot.materialSequence);
  const materialDiversity=new Set(sequences).size===3;
  const deterministicReplay=replayProof(lots[1])===replayProof(lots[3]);
  const totalPhysicalProducts=lots.slice(0,3).reduce((n,lot)=>n+lot.produced,0);
  const acceptedPhysicalProducts=lots.slice(0,3).reduce((n,lot)=>
   n+lot.trace.filter(t=>t.qualityPassed).length,0);
  const qualityYieldPercent=totalPhysicalProducts>0?
   Math.round(acceptedPhysicalProducts/totalPhysicalProducts*10000)/100:0;
  const throughput=lots.slice(0,3).map(lot=>lot.throughputPerSimHour);
  const sourcePreserved=projectSignature(p)===sourceSignature;
  const pass=lots.every(lot=>lot.pass)&&materialDiversity&&deterministicReplay&&
   sourcePreserved&&totalPhysicalProducts===expectedProducts*3&&
   acceptedPhysicalProducts===totalPhysicalProducts;
  return {...base,lots,materialDiversity,deterministicReplay,
   totalPhysicalProducts,acceptedPhysicalProducts,qualityYieldPercent,
   minModelThroughputPerHour:Math.min(...throughput),
   maxModelThroughputPerHour:Math.max(...throughput),
   status:pass?'passed':'failed',
   diagnostic:pass?
    'Three genuinely different feeder-seeded material lots and independent first/middle/final equipment faults passed the same real PLC program; body-level product quality and replay were physically checked in isolated Workers. Educational model only.':
    'Material-lot variation, worker-owned physical quality, true source provenance, fault recovery, replay or project integrity failed; no passing certificate issued'};
 }catch(error){
  return {...base,status:'failed',diagnostic:'P17 real-material campaign aborted without a pass: '+
   (error instanceof Error?error.message:String(error))};
 }
}
